package com.rekluzlabs.makokolorizeimport android.net.Uriimport android.os.Bundleimport androidx.activity.ComponentActivityimport androidx.activity.compose.BackHandlerimport androidx.activity.compose.setContentimport androidx.activity.enableEdgeToEdgeimport androidx.compose.animation.Crossfadeimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.material3.Surfaceimport androidx.compose.runtime.Composableimport androidx.compose.runtime.getValueimport androidx.compose.runtime.mutableStateOfimport androidx.compose.runtime.rememberimport androidx.compose.runtime.setValueimport androidx.compose.ui.Modifierimport androidx.compose.ui.platform.LocalContextimport com.rekluzlabs.makokolorize.ui.screens.HomeScreenimport com.rekluzlabs.makokolorize.ui.screens.ResultScreenimport com.rekluzlabs.makokolorize.ui.screens.RestoreRouteimport com.rekluzlabs.makokolorize.ui.screens.SettingsScreenimport com.rekluzlabs.makokolorize.ui.theme.MakokolorizeThemeclass MainActivity : ComponentActivity() {    override fun onCreate(savedInstanceState: Bundle?) {        super.onCreate(savedInstanceState)        enableEdgeToEdge()        setContent {            MakokolorizeTheme {                Surface(modifier = Modifier.fillMaxSize()) {                    AppNavigation()                }            }        }    }}sealed class AppScreen {    data object Home : AppScreen()    data object Settings : AppScreen()    data class Restore(val imageUri: Uri) : AppScreen()    data class Result(val imageUri: Uri, val resultUri: Uri) : AppScreen()}@Composablefun AppNavigation() {    var currentScreen by remember { mutableStateOf<AppScreen>(AppScreen.Home) }    val context = LocalContext.current    BackHandler(enabled = currentScreen !is AppScreen.Home) {        currentScreen = when (currentScreen) {            is AppScreen.Restore -> AppScreen.Home            is AppScreen.Result -> {                val result = currentScreen as AppScreen.Result                AppScreen.Restore(result.imageUri)            }            is AppScreen.Settings -> AppScreen.Home            else -> AppScreen.Home        }    }    Crossfade(targetState = currentScreen, label = "screen") { screen ->        when (screen) {            is AppScreen.Home -> {                HomeScreen(                    onImageSelected = { uri ->                        currentScreen = AppScreen.Restore(uri)                    },                    onNavigateToSettings = {                        currentScreen = AppScreen.Settings                    },                    context = context                )            }            is AppScreen.Settings -> {                SettingsScreen(                    onBack = { currentScreen = AppScreen.Home }                )            }            is AppScreen.Restore -> {                RestoreRoute(                    imageUri = screen.imageUri,                    onResultReady = { resultUri ->                        currentScreen = AppScreen.Result(screen.imageUri, resultUri)                    },                    onBack = { currentScreen = AppScreen.Home }                )            }            is AppScreen.Result -> {                ResultScreen(                    originalUri = screen.imageUri,                    resultUri = screen.resultUri,                    onBack = {                        currentScreen = AppScreen.Restore(screen.imageUri)                    },                    onReRun = {                        currentScreen = AppScreen.Restore(screen.imageUri)                    }                )            }        }    }}